CREATE TABLE N AS SELECT value j FROM generate_series(0,259);CREATE TABLE C AS WITH RECURSIVE Z(p,q,u,v)AS(SELECT key,0,j%4,j/4 FROM json_each('[240,102,114,54,99,113,116]'),N WHERE j<16 AND value>>j&1 UNION ALL SELECT p,q+1,2+(p<1)-v,u-(p=1)FROM Z WHERE q<3)SELECT*FROM Z;CREATE INDEX I ON C(p,q);CREATE TABLE g AS SELECT 0 s,7 c,0 x,0 y,0 r,0 t,0 w,0 l,0 k,0 d,0 o,printf('%0200d%.60c',0,8)b;CREATE TABLE ev(e);CREATE VIEW Q AS SELECT j,a,f,i,EXISTS(SELECT 1 FROM C WHERE p=c AND q=i AND((a+u+10)/10-1 OR substr(b,(f+v)*10+a+u+1,1)))z FROM(SELECT*,x+m*(1-j%2*2)*(j+1)/2 a,y+j-m*j f,(r+(k=3))%4 i FROM(SELECT*,k<4 AND k m FROM g),N WHERE iif(m,k=3 AND j<5 OR j=k,j<21));CREATE VIEW V AS SELECT j,coalesce((SELECT e+1 FROM(SELECT c e,x a,y f,r i WHERE NOT o UNION ALL SELECT s%7,0,21,0),C WHERE p=e AND q=i AND(f+v)*10+a+u=j),substr(b,j+1,1))+0 d FROM g,N;CREATE VIEW W AS SELECT j/10 y,group_concat(iif(d>7,'  ','[38;5;'||(substr('237 51226135 46196 33208',d*3+1,3)+0)||iif(d,'m██}','m ·}')),''ORDER BY j)t FROM V WHERE j<200 OR j%10<4 GROUP BY 1;CREATE TRIGGER T INSERT ON ev BEGIN UPDATE g SET k=iif(s,max(NEW.e,(t+NOT NEW.e)/max(1,10-l/10)*4),5),t=(t+NOT NEW.e)%max(1,10-l/10),o=NEW.e=9,d=0,s=s+(s=0)*NEW.e*16807%2147483647;UPDATE g SET x=a,r=i,y=y+iif(k=5,m-1,k=4 AND m>1),d=k=5 OR k=4 AND m<2 FROM(SELECT a,i FROM Q WHERE NOT z ORDER BY j LIMIT 1),(SELECT min(j)m FROM Q WHERE z);UPDATE g SET w=w+substr('00000040010003001200',e*4+1,4)*(l/10+1),l=l+e,b=hex(zeroblob(e*5))||F||substr(b,201),c=s%7,s=s*16807%2147483647,x=3,y=0,r=0,t=0 FROM(SELECT group_concat(q,''ORDER BY y)F,20-count(*)e FROM(SELECT j/10 y,group_concat(d,''ORDER BY j)q FROM V GROUP BY 1)WHERE instr(q,0))WHERE d;UPDATE g SET o=(SELECT z FROM Q WHERE j=0)WHERE d;END;CREATE VIEW frame AS SELECT replace(replace(replace(replace(replace(replace('[H  [1;38;5;75mS Q L I T E T R I S}[K
